css:
.so * {
    font-family: Calibri, Arial, sans-serif;
font-size: 11px;
color: #333;
line-height: 1.4;
}
.so table { width: 100%; }
.so .bt {
    border-collapse: separate;
border-spacing: 0;
}
.so .bt td, .so .bt th {
    border-right: 1px solid #aaa;
border-bottom: 1px solid #aaa;
padding: 4px 6px;
vertical-align: top;
-webkit-box-decoration-break: clone;
box-decoration-break: clone;
}
.so .bt td:first-child,
.so .bt th:first-child {
    border-left: 1px solid #aaa;
}
.so .bt thead th {
    border-top: 1px solid #aaa;
background: #f0f0f0;
font-weight: bold;
font-size: 11px;
}
.so .bt tbody tr:first-child td {
    border-top: 1px solid #aaa;
}
.so .bt thead { display: table-header-group; }
.so .bt tbody { display: table-row-group; }
.so .bt tr { page-break-inside: auto; break-inside: auto; }
.so .bt td {
    page-break-inside: auto; break-inside: auto;
overflow-wrap: break-word; word-wrap: break-word;
}
.so .desc-cell {
    overflow-wrap: break-word; word-wrap: break-word;
word-break: break-word; max-width: 0;
}
.so .desc-cell p, .so .desc-cell div, .so .desc-cell span {
    margin: 0 !important; padding: 0 !important; display: inline;
}
.so .desc-cell img { max-width: 100%; height: auto; }
.so .nb td { border: none; padding: 2px 4px; }
.so .r  { text-align: right; }
.so .c  { text-align: center; }
.so .b  { font-weight: bold; }
.so .doc-title {
    text-align: center;
font-size: 14px;
font-weight: bold;
color: #2c3e50;
margin: 6px 0 10px;
}
.so .stitle {
    font-size: 12px; font-weight: bold; color: #2c3e50;
margin: 10px 0 3px; border-bottom: 1px solid #2c3e50;
padding-bottom: 2px; page-break-after: avoid; break-after: avoid;
}
.so .totals {
    width: 45%; margin-left: auto;
page-break-inside: avoid; break-inside: avoid;
}
.so .totals td { padding: 2px 6px; border: none; }
.so .gt td {
    border-top: 2px solid #2c3e50;
font-weight: bold; font-size: 12px; padding-top: 4px;
}
.so .iw { font-size: 10px; font-style: italic; margin-top: 4px; color: #555; }
.so .info-table { page-break-inside: avoid; break-inside: avoid; }
/* Company header */
.so .company-header {
    border-bottom: 2px solid #2c3e50;
padding-bottom: 8px;
margin-bottom: 10px;
}
.so .company-header td { border: none; padding: 2px 0; }
.so .company-name { font-size: 18px; font-weight: bold; color: #2c3e50; }
.so .company-detail { font-size: 10px; color: #555; }

body { margin:0; background:white !important; }
* { 
    -webkit-print-color-adjust:exact !important; 
print-color-adjust:exact !important; 
}
thead { display:table-header-group; }
tfoot { display:table-footer-group; }
tbody { display:table-row-group; }
tr { 
    page-break-inside:auto; 
break-inside:auto; 
}
td, th {
    page-break-inside:auto; 
break-inside:auto;
overflow-wrap:break-word; 
word-wrap:break-word;
-webkit-box-decoration-break:clone; 
box-decoration-break:clone;

}
td div, td p, td span {
    page-break-inside:auto; 
break-inside:auto;
overflow-wrap:break-word; 
word-wrap:break-word;

}
h1,h2,h3,h4,h5,h6 { 
    page-break-after:avoid; 
break-after:avoid; 

}
